require_once __DIR__.'/../includes/layout.php';require_once __DIR__.'/../includes/auth.php';$admin=require_admin();$id=(int)($_GET['id']??0);$q=db()->prepare("SELECT c.*,d.body_id,d.current_mortuary,d.current_storage_location,d.body_bag_no,d.seal_no FROM cases c JOIN deceased_details d ON d.case_id=c.id WHERE c.id=? AND c.deleted_at IS NULL");$q->execute([$id]);$case=$q->fetch();if(!$case){http_response_code(404);exit('Deceased/DVI case not found.');}
if($_SERVER['REQUEST_METHOD']==='POST'&&can_manage_dvi($admin['role'])){verify_csrf();$type=$_POST['event_type']??'other';$allowed=['recovered','bagged','sealed','received','transferred','pm_started','pm_completed','sample_collected','stored','other'];if(!in_array($type,$allowed,true))$type='other';$dt=trim((string)($_POST['event_datetime']??''));$dt=$dt!==''?str_replace('T',' ',$dt).(strlen($dt)<=16?':00':''):date('Y-m-d H:i:s');$to=trim((string)($_POST['to_location']??''));db()->prepare('INSERT INTO body_custody_events(case_id,event_type,event_datetime,event_date_bs,from_location,to_location,body_bag_no,seal_no,handled_by_name,handled_by_post,handled_by_office,admin_id,notes) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$id,$type,$dt,trim((string)($_POST['event_date_bs']??'')),trim((string)($_POST['from_location']??'')),$to,trim((string)($_POST['body_bag_no']??'')),trim((string)($_POST['seal_no']??'')),trim((string)($_POST['handled_by_name']??$admin['name'])),trim((string)($_POST['handled_by_post']??$admin['post_title'])),trim((string)($_POST['handled_by_office']??$admin['office_name'])),$admin['id'],trim((string)($_POST['notes']??''))]);if($to!=='')db()->prepare('UPDATE deceased_details SET current_storage_location=?,updated_at=NOW() WHERE case_id=?')->execute([$to,$id]);audit($admin['id'],'add_custody_event',$id,$type.' -> '.$to);flash('success','Chain-of-custody event recorded.');redirect(base_url('admin/custody.php?id='.$id));}
$e=db()->prepare('SELECT x.*,a.name admin_name FROM body_custody_events x LEFT JOIN admins a ON a.id=x.admin_id WHERE x.case_id=? ORDER BY x.event_datetime DESC,x.id DESC');$e->execute([$id]);$events=$e->fetchAll();page_header('Chain of Custody',true);
